// Client loader for the sourced-context library generated by scripts/build-library.ts.
//
//   /library/index.json            LibraryIndex
//   /library/{packId}/{BOOK}.json  ExcerptShard (or CrossRefShard for the "openbible" pack)
//
// Shards are cached in Dexie (`libraryCache`, id `${packId}/${BOOK}`) so the library works
// offline once a book has been opened. Nothing here creates text: every excerpt is a verbatim
// slice of a downloaded source, verified at build time by scripts/verify-excerpts.ts.

import type { CrossRef, Era, Excerpt, LibraryCacheEntry, SourceType, SourceWork, VerseRange } from "@/db/types";
import { BOOK_CODES } from "@/lib/books";
import { compareRefs, rangesOverlap } from "@/lib/refs";

// ---------------------------------------------------------------- data shapes (shared with scripts)

/** Excerpt as written to shards. Extra fields beyond Excerpt are optional. */
export interface LibraryExcerpt extends Excerpt {
  /** JSON sources (Creeds.json): field paths; text = field values joined by "\n" (e.g. Q then A). */
  sourcePaths?: string[];
  /** Offsets of each part into its normalized field value (partOffsets[0] === charOffset). */
  partOffsets?: number[];
  /** HTML sources: the verified source text is the page with markup removed. */
  sourceTransform?: "html-text";
  /** The full (also verified) section that another excerpt's sectionId points at. */
  fullSection?: boolean;
}

export interface LibraryWork extends SourceWork {
  excerptCount: number;
  crossrefCount: number;
  ocrNote?: string;
  /** Listed for reference; no verse mapping. */
  listedOnly?: boolean;
}

export interface LibraryIndex {
  generatedAt: string;
  works: LibraryWork[];
  /** packId -> books that have a shard file */
  books: Record<string, string[]>;
  /** packs not built, with the reason (unreachable source, license, largePack) */
  skipped: { id: string; reason: string }[];
}

export interface ExcerptShard { workId: string; book: string; excerpts: LibraryExcerpt[] }
export interface CrossRefShard { workId: string; book: string; crossrefs: CrossRef[] }

export const CROSSREF_PACK_ID = "openbible";

export const ERA_LABELS: Record<Era, string> = {
  early: "Early Church",
  medievalReformation: "Medieval & Reformation",
  puritan18c: "Puritan & 18th c.",
  c19: "19th c.",
  c20early: "Early 20th c.",
  modern: "Modern",
};

export const ERA_ORDER: Era[] = ["early", "medievalReformation", "puritan18c", "c19", "c20early", "modern"];

export const TYPE_LABELS: Record<SourceType, string> = {
  commentary: "Commentary",
  sermon: "Sermon",
  apologetics: "Apologetics",
  theology: "Theology",
  confession: "Confession",
  catechism: "Catechism",
  devotional: "Devotional",
  crossref: "Cross-references",
};

export const MAPPING_LABELS: Record<Excerpt["mappingMethod"], string> = {
  heading: "Mapped by the work's heading",
  scriptureIndex: "Mapped by the work's scripture index",
  inlineCitation: "Mapped by a citation in the text",
  proofText: "Mapped by the document's proof texts",
  sermonText: "Mapped by the sermon's text",
  entryVerse: "Mapped by the entry's verse",
};

// ---------------------------------------------------------------- loading

type FetchJson = (url: string) => Promise<unknown>;

interface CacheLike {
  get(id: string): Promise<LibraryCacheEntry | undefined>;
  put(entry: LibraryCacheEntry): Promise<unknown>;
}

let basePath = "/library";
let fetchJson: FetchJson = async (url) => {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status} for ${url}`);
  return res.json();
};
let cacheOverride: CacheLike | null | undefined;
let indexPromise: Promise<LibraryIndex> | null = null;
const shardMemo = new Map<string, Promise<ExcerptShard | CrossRefShard | null>>();

/** Test/SSR hook: replace fetch, base path, or the Dexie cache (null disables caching). */
export function configureLibrary(opts: { fetchJson?: FetchJson; basePath?: string; cache?: CacheLike | null }): void {
  if (opts.fetchJson) fetchJson = opts.fetchJson;
  if (opts.basePath !== undefined) basePath = opts.basePath;
  if (opts.cache !== undefined) cacheOverride = opts.cache;
  clearLibraryMemo();
}

export function clearLibraryMemo(): void {
  indexPromise = null;
  shardMemo.clear();
}

async function getCache(): Promise<CacheLike | null> {
  if (cacheOverride !== undefined) return cacheOverride;
  if (typeof indexedDB === "undefined") return null;
  const { db } = await import("@/db/db");
  return db.libraryCache;
}

export function loadLibraryIndex(): Promise<LibraryIndex> {
  indexPromise ??= (fetchJson(`${basePath}/index.json`) as Promise<LibraryIndex>).catch((e) => {
    indexPromise = null;
    throw e;
  });
  return indexPromise;
}

/**
 * One pack's shard for one book. Network first (fresh after an app update), falling back to the
 * Dexie copy when offline. Returns null when the pack has no excerpts for that book.
 */
export function loadShard(packId: string, book: string): Promise<ExcerptShard | CrossRefShard | null> {
  const id = `${packId}/${book}`;
  let p = shardMemo.get(id);
  if (!p) {
    p = (async () => {
      const index = await loadLibraryIndex().catch(() => null);
      if (index && !(index.books[packId] ?? []).includes(book)) return null;
      const cache = await getCache().catch(() => null);
      try {
        const data = (await fetchJson(`${basePath}/${packId}/${book}.json`)) as ExcerptShard | CrossRefShard;
        await cache?.put({ id, packId, book, data, fetchedAt: Date.now() }).catch(() => undefined);
        return data;
      } catch (e) {
        const hit = await cache?.get(id).catch(() => undefined);
        if (hit) return hit.data as ExcerptShard | CrossRefShard;
        throw e;
      }
    })();
    p.catch(() => shardMemo.delete(id));
    shardMemo.set(id, p);
  }
  return p;
}

// ---------------------------------------------------------------- queries

function booksOf(range: VerseRange): string[] {
  const a = BOOK_CODES.indexOf(range.start.book);
  const b = BOOK_CODES.indexOf(range.end.book);
  return a < 0 || b < 0 ? [] : BOOK_CODES.slice(a, b + 1);
}

/** Verse-count estimate for ordering (no meta needed): chapters count as 30 verses. */
export function approxRangeSize(r: VerseRange): number {
  const books = BOOK_CODES.indexOf(r.end.book) - BOOK_CODES.indexOf(r.start.book);
  return books * 1000 * 30 + (r.end.chapter - r.start.chapter) * 30 + (r.end.verse - r.start.verse) + 1;
}

function specificity(ex: Excerpt, range: VerseRange): number {
  const overlapping = ex.verseRanges.filter((r) => rangesOverlap(r, range));
  return Math.min(...overlapping.map(approxRangeSize));
}

/**
 * Excerpts from the enabled packs whose verseRanges overlap `range`, most specific first
 * (smallest mapped range), then canonical order. Full-section excerpts are excluded unless asked
 * for (they are reached through sectionId).
 */
export async function excerptsForRange(
  range: VerseRange, enabledPackIds: string[], opts: { includeSections?: boolean } = {},
): Promise<LibraryExcerpt[]> {
  const index = await loadLibraryIndex();
  const packs = index.works.filter((w) => enabledPackIds.includes(w.id) && w.parser !== "openbible-crossrefs" && !w.listedOnly);
  const seen = new Set<string>();
  const out: LibraryExcerpt[] = [];
  const books = booksOf(range);
  const shards = await Promise.all(
    packs.flatMap((w) => books.map((b) => loadShard(w.id, b).catch(() => null))),
  );
  for (const s of shards) {
    if (!s || !("excerpts" in s)) continue;
    for (const ex of s.excerpts) {
      if (seen.has(ex.id)) continue;
      if (ex.fullSection && !opts.includeSections) continue;
      if (!ex.verseRanges.some((r) => rangesOverlap(r, range))) continue;
      seen.add(ex.id);
      out.push(ex);
    }
  }
  const spec = new Map(out.map((e) => [e.id, specificity(e, range)]));
  return out.sort(
    (a, b) => spec.get(a.id)! - spec.get(b.id)! || compareRefs(a.verseRanges[0].start, b.verseRanges[0].start) || a.id.localeCompare(b.id),
  );
}

/** The full section an excerpt belongs to ("Read full section"), if any. */
export async function sectionFor(ex: LibraryExcerpt): Promise<LibraryExcerpt | null> {
  if (!ex.sectionId) return null;
  for (const b of new Set(ex.verseRanges.flatMap(booksOf))) {
    const s = await loadShard(ex.workId, b).catch(() => null);
    const hit = s && "excerpts" in s ? s.excerpts.find((e) => e.id === ex.sectionId) : undefined;
    if (hit) return hit;
  }
  return null;
}

/** OpenBible cross references whose `from` verse lies in `range`, by votes (desc). */
export async function crossRefsForRange(range: VerseRange, packId = CROSSREF_PACK_ID): Promise<CrossRef[]> {
  const out: CrossRef[] = [];
  for (const b of booksOf(range)) {
    const s = await loadShard(packId, b).catch(() => null);
    if (!s || !("crossrefs" in s)) continue;
    for (const x of s.crossrefs) {
      const [book, c, v] = x.from.split(".");
      const ref = { book, chapter: Number(c), verse: Number(v) };
      if (compareRefs(range.start, ref) <= 0 && compareRefs(ref, range.end) <= 0) out.push(x);
    }
  }
  return out.sort((a, b) => b.votes - a.votes);
}

/** Pack ids enabled by default (Settings.enabledPacks initial value). */
export async function defaultEnabledPackIds(): Promise<string[]> {
  const index = await loadLibraryIndex();
  return index.works.filter((w) => w.defaultEnabled).map((w) => w.id);
}
